import z3
import itertools

N = 11

edges = {}
for i in range(N):
    for j in range(i+1, N):
        edges[(i, j)] = z3.Bool(f"e_{i}_{j}")

solver = z3.Solver()

known_edges = [(0,6), (1,10), (3,6), (3,8), (2,7), (0,4), (1,6), (0,8), (1,2), (5,10), (0,3)]
for i in range(N):
    for j in range(i+1, N):
        if (i, j) in known_edges or (j, i) in known_edges:
            solver.add(edges[(min(i, j), max(i, j))] == True)

for subset in itertools.combinations(range(N), 5):
    clause = []
    for i, j in itertools.combinations(subset, 2):
        clause.append(edges[(min(i, j), max(i, j))])
    solver.add(z3.Or(clause))

for removed in itertools.combinations(range(N), 2):
    remaining = [v for v in range(N) if v not in removed]
    for i in range(1, (1 << 8)):
        set_A = [remaining[0]]
        set_B = []
        for j in range(8):
            if (i >> j) & 1:
                set_A.append(remaining[j+1])
            else:
                set_B.append(remaining[j+1])

        if not set_B:
            continue

        clause = []
        for u in set_A:
            for v in set_B:
                clause.append(edges[(min(u, v), max(u, v))])
        solver.add(z3.Or(clause))

if solver.check() == z3.sat:
    m = solver.model()
    result = []
    for i in range(N):
        for j in range(i+1, N):
            if z3.is_true(m.evaluate(edges[(i, j)])):
                result.append((i, j))
    print(result)
else:
    print("UNSATISFIABLE")
